import{_ as l,l as o,o as a,c as s,v as t,p as n,x as i,d as M,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"VMX 与 VM exit","description":"","frontmatter":{"title":"VMX 与 VM exit","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vmx-vmexit.md","filePath":"cs/vmx-vmexit.md","lastUpdated":1789023840000}'),V={name:"cs/vmx-vmexit.md"};function c(x,e,h,m,_,E){const r=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="vmx-与-vm-exit" tabindex="-1">VMX 与 VM exit <a class="header-anchor" href="#vmx-与-vm-exit" aria-label="Permalink to &quot;VMX 与 VM exit&quot;">​</a></h1><div class="epigraph"><p>VMX（SVM）让 CPU 进入非根模式跑客户：敏感操作触发 VM-exit，把控制交还 VMM，VMCS 记下原因与寄存器。</p><footer>—— 据 Intel SDM 对 VMX 的说明；AMD SVM；Popek 条件的硬件实现</footer></div><p><a href="/cs/kvm-qemu">KVM</a> 的 <code>KVM_RUN</code> 底下是 <strong>VM-entry/exit</strong>。缺口是硬件：VMCS、退出原因，不是 ARM 全部异常模型（同构点到）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>客户执行 I/O、cpuid、关中断过久、EPT 违例 → exit。缺口：exit 贵（微秒级以下但仍远贵于普通 syscall 路径的优化目标）；要减少 exit。本课不把 VMCS 字段当考试。</p><p><span class="marginnote">APIC 虚拟化、posted interrupt 后课减少中断开销。对象是陷入原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VMM 填 VMCS → VMLAUNCH/VMRESUME → 客户跑 → exit → KVM 处理或回 QEMU。对照 <a href="/cs/syscall-path">syscall</a>：都是特权切换，入口不同。对照 <a href="/cs/napi">NAPI</a>：设备 IRQ 可使客户 exit。对照 KPTI：宿主机自己的隔离。</p>',8)),(a(),n(d,null,{default:i(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22VM-entry%22%5D%20--%3E%20G%5B%22%E5%AE%A2%E6%88%B7%E9%9D%9E%E6%A0%B9%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20G%20--%3E%20EX%5B%22%E6%95%8F%E6%84%9F%E6%93%8D%E4%BD%9C%20VM-exit%22%5D%0A%20%20EX%20--%3E%20VMM%5B%22KVM%2FQEMU%20%E5%A4%84%E7%90%86%22%5D%0A%20%20VMM%20--%3E%20EN%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[M(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬件虚拟化把 Popek 的陷入变成 CPU 模式，使未改过的 OS 可当客户。性能等于「少 exit」。不要写成指令集课全文。与 <a href="/cs/kernel-hardening">hardening</a>：客户不能直接执行宿主页。</p><p>错误配置 VMCS 导致立即 exit 循环。</p><p>实现上：exit 原因决定热路径：MMIO 仍贵，halt 可接受。VMCS 有宿主板和客户板，嵌套时还有影子。错误的中断窗口设置会导致时钟中断丢。 读法上只引用<a href="/cs/kvm-qemu">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>VMX 与 VM exit</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 exit qualification。不保证嵌套虚拟化的每次双重 exit——后课。下一课内存：影子页表。</p><p>版本字段会变，课序钉的是机制对象「VMX 与 VM exit」，不是某一主线内核的结构体名。 后课默认：客户敏感操作会 VM-exit。客户页表如何嵌套翻译，下一课影子页表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VMX 非根模式跑客户；敏感操作 exit。</li><li>VMCS 保存状态与原因。</li><li>影子页表是下一课。</li><li>出处：Intel SDM VMX；KVM；Popek。</li></ul>',11))])}const S=l(V,[["render",c]]);export{f as __pageData,S as default};
